        "٢. لكي يتزن الجسم تحت تأثير هاتين القوتين، يجب أن تكونا متساويتين في المقدار ومتضادتين في الاتجاه ولهما نفس خط العمل.",
        "٣. وبالتالي، فإن المستقيم الواصل بين نقطة التعليق $A$ ومركز الثقل $G$ يجب أن يكون رأسياً.",
