      "questionAr": "قضيب منتظم $AB$ طوله $80\\text{ cm}$ ووزنه $60\\text{ N}$، مركز ثقله عند منتصفه (على بعد $40\\text{ cm}$ من $A$). ما مقدار الثقل $W$ الواجب تعليقه عند الطرف $B$ بحيث ينزاح مركز ثقل المجموعة إلى نقطة تبعد $50\\text{ cm}$ عن $A$؟",
