      "questionAr": "مجموعة كتل كتلتها الكلية $M = 20\\text{ kg}$ ومركز ثقلها عند نقطة الأصل $O$. إذا أُزيحت كتلة داخلية $m = 4\\text{ kg}$ مسافة قدرها $15\\text{ cm}$ في الاتجاه الموجب لمحور السينات، فما المسافة التي ينزاح بها مركز ثقل المجموعة ككل؟",
