        "3. The shift in center of gravity is: $\\Delta x_G = \\frac{m \\cdot \\Delta x}{M}$.",
        "4. Substitute values: $\\Delta x_G = \\frac{4 \\times 15}{20} = \\frac{60}{20} = 3\\text{ cm}$."
