      "difficulty": "easy",
      "questionEn": "In calculating the center of gravity of a uniform lamina with a cutout section (portion removed), what does the 'negative mass method' entail?",
      "questionAr": "عند حساب مركز ثقل صفيحة منتظمة مقتطع منها جزء، ماذا تعني 'طريقة الكتلة السالبة'؟",
