      "questionAr": "صفيحة مستطيلة منتظمة $ABCD$ ضلعها $AB = 20\\text{ cm}$ على محور السينات وضلعها $AD = 10\\text{ cm}$ على محور الصادات، حيث $A(0, 0)$ ومركزها عند $(10, 5)$. حُفر ثقب دائري نصف قطره $r = 2\\text{ cm}$ مركزه عند $(15, 5)$. ما الإحداثي السيني لمركز ثقل الصفيحة المتبقية بدلالة $\\pi$؟",
