      "hintEn": "Rectangle area = 200 at (10, 5). Hole area = 4*pi at (15, 5). x_G = (200(10) - 4*pi(15)) / (200 - 4*pi) = (2000 - 60*pi) / (4(50 - pi)) = (500 - 15*pi) / (50 - pi) cm.",
      "hintAr": "مساحة المستطيل = 200 عند (10، 5). مساحة الثقب = 4 ط عند (15، 5). س_م = (2000 - 60 ط) / (200 - 4 ط) = (500 - 15 ط) / (50 - ط) سم.",
