        "3. Remaining area: $200 - 4\\pi = 4(50 - \\pi)$.",
        "4. Apply negative mass formula: $x_G = \\frac{200(10) - 4\\pi(15)}{200 - 4\\pi} = \\frac{2000 - 60\\pi}{4(50 - \\pi)} = \\frac{500 - 15\\pi}{50 - \\pi}\\text{ cm}$.",
