      "hintAr": "عزم س = 18(8/3) = 48. عزم ص = 18(2) + 6 و = 36 + 6 و. لكي تصنع زاوية 45°: س_م = ص_م، إذن 48 = 36 + 6 و، ومنها 6 و = 12، و = 2 نيوتن.",
