      "questionAr": "قضيب غير منتظم $AB$ طوله $100\\text{ cm}$ يتزن أفقياً على وتد يرتكز على بعد $40\\text{ cm}$ من الطرف $A$. إذا عُلّق ثقل قدره $10\\text{ N}$ عند الطرف $A$، وجب نقل الوتد إلى مسافة $30\\text{ cm}$ من $A$ ليظل القضيب متزناً أفقياً. ما وزن القضيب؟",
