      "questionAr": "سلك منتظم فيه $AB = AC = 16\\text{ cm}$ منحنٍ عند $A$ بزاوية $\\angle BAC = 120^\\circ$ عُلّق تعليقاً حراً من الطرف $B$. ما ظل الزاوية التي يصنعها الذراع $BA$ مع الأفقي في وضع الاتزان؟",
