      "hintAr": "نأخذ B نقطة أصل و BA على السينات. منتصف BA عند (8، 0). منتصف AC عند (20، 4 جذر 3). مركز الثقل = (14، 2 جذر 3). ظا الزاوية مع الأفقي = 2 جذر 3 / 14 = جذر 3 / 7.",
