      "questionEn": "At what distance from the center of its circular base along the axis of symmetry is the center of gravity of a uniform thin hemispherical shell (hollow hemisphere) of radius $r$ located?",
      "questionAr": "على أي بعد من مركز قاعدتها الدائرية على محور التماثل يقع مركز ثقل قشرة نصف كروية رقيقة منتظمة (نصف كرة مجوف) نصف قطرها $r$؟",
