      "hintAr": "الجزء 1: مساحته 40 ومركزه (5، 2). الجزء 2: مساحته 24 ومركزه (2، 7). المساحة الكلية = 64. س_م = (200 + 48) / 64 = 31/8 سم. ص_م = (80 + 168) / 64 = 31/8 سم.",
