      "hintAr": "لكي يكون الاتزان مستقراً على السطح الكروي، يجب أن يقع مركز ثقل الجسم ككل أسفل المركز الهندسي للكرة: ع^2 / 2 <= نق^2 / 4، إذن ع <= نق / جذر 2.",
