      "questionAr": "قضيب رفيع منتظم $AB$ طوله $60\\text{ cm}$ ووزنه $20\\text{ N}$ متصل عند طرفه $A$ بكرة مصمتة وزنها $30\\text{ N}$ ونصف قطرها $5\\text{ cm}$ (مركز الكرة عند $A$)، ومتصل عند طرفه $B$ بكرة مصمتة أخرى وزنها $50\\text{ N}$ ونصف قطرها $10\\text{ cm}$ (مركز الكرة عند $B$). على أي بعد من مركز الكرة عند $A$ يقع مركز ثقل المجموعة ككل؟",
