      "hintAr": "نأخذ A نقطة أصل. الكرة A: وزنها 30 عند س = 0. القضيب: وزنه 20 عند س = 30. الكرة B: وزنها 50 عند س = 60. الوزن الكلي = 100 نيوتن. س_م = (600 + 3000) / 100 = 36 سم.",
      "stepByStepSolutionEn": [
        "1. For any uniform sphere, the center of gravity is at its geometric center, regardless of its radius.",
        "2. Set coordinate axis along the rod with origin at the center of sphere $A$ ($x_A = 0$).",
        "3. Sphere at $A$: weight $W_1 = 30\\text{ N}$ at $x_1 = 0$.",
        "4. Uniform rod $AB$: length $60\\text{ cm}$, weight $W_{\\text{rod}} = 20\\text{ N}$ at midpoint $x_{\\text{rod}} = 30\\text{ cm}$.",
        "5. Sphere at $B$: weight $W_2 = 50\\text{ N}$ at $x_2 = 60\\text{ cm}$.",
        "6. Total weight: $W = 30 + 20 + 50 = 100\\text{ N}$.",
        "7. $x_G = \\frac{30(0) + 20(30) + 50(60)}{100} = \\frac{600 + 3000}{100} = \\frac{3600}{100} = 36\\text{ cm}$."
      ],
      "stepByStepSolutionAr": [
        "١. مركز ثقل أي كرة مصمتة منتظمة يقع عند مركزها الهندسي بغض النظر عن نصف قطرها.",
        "٢. نعتبر مركز الكرة عند $A$ هو نقطة الأصل ($x_A = 0$).",
        "٣. الكرة عند $A$: وزنها 30 نيوتن عند $x_1 = 0$.",
        "٤. القضيب المنتظم: وزنه 20 نيوتن عند منتصفه $x = 30$ سم.",
        "٥. الكرة عند $B$: وزنها 50 نيوتن عند $x_2 = 60$ سم.",
        "٦. الوزن الكلي: $100$ نيوتن.",
        "٧. $x_G = \\frac{20(30) + 50(60)}{100} = \\frac{3600}{100} = 36$ سم."
      ],
      "teacherTipEn": "Key principle: The radius of a sphere does not displace its center of gravity from its geometric center.",
      "teacherTipAr": "مبدأ أساسي: نصف قطر الكرة لا يغير موضع مركز ثقلها، فهو يظل دائماً عند المركز الهندسي للكرة."
