      "difficulty": "hots",
      "questionEn": "A uniform wire is bent to form five sides of a regular hexagon $ABCDEF$ of side length $a = 6\\text{ cm}$, with side $AF$ left open. If the center of the hexagon is at the origin $O(0, 0)$ and the missing side $AF$ is parallel to the y-axis at $x = 3\\sqrt{3}\\text{ cm}$, what is the distance of the center of gravity of the wire frame from the center $O$?",
      "questionAr": "سلك منتظم ثُني ليشكل خمسة أضلاع من مسدس منتظم $ABCDEF$ طول ضلعه $a = 6\\text{ cm}$، وتُرك الضلع $AF$ مفتوحاً. إذا كان مركز المسدس عند نقطة الأصل $O(0, 0)$ والضلع المفقود $AF$ موازياً لمحور الصادات عند $x = 3\\sqrt{3}\\text{ cm}$، ما بعد مركز ثقل الإطار السلكي عن المركز $O$؟",
