      "questionAr": "صفيحة مربعة منتظمة $ABCD$ طول ضلعها $12\\text{ cm}$ مع $A(0, 0)$ والضلع $AB$ على محور السينات، اقتُطع منها المثلث الركني ذو الرؤوس $(0, 0)$ و $(6, 0)$ و $(0, 6)$ (ومركز ثقلها يقع عند $(\\frac{46}{7}, \\frac{46}{7})$). إذا عُلّقت الصفيحة المتبقية تعليقاً حراً من الرأس $B(12, 0)$، فما ظل الزاوية التي يصنعها الضلع $BC$ مع الخط الرأسي؟",
