      "hintAr": "السلك المتبقي هو قوس دائري زاويته المركزية 2(ط - α). قانون مركز ثقل القوس الدائري بنصف زاوية بيتا هو: نق جا بيتا / بيتا = نق جا α / (ط - α).",
