      "hintEn": "Hexagon = 6 equal equilateral triangles. Removed triangle has centroid at 2/3 of altitude from O. Altitude h = 12 * sin(60) = 6*sqrt(3). Centroid is at (2/3)*6*sqrt(3) = 4*sqrt(3) cm from O. Negative mass: d = (6(0) - 1(4*sqrt(3))) / 5 = 4*sqrt(3) / 5 cm.",
      "hintAr": "المسدس = 6 مثلثات متساوية الأضلاع. المثلث المقتطع مركزه يبعد ثلثي الارتفاع عن O: (2/3) × 6 جذر 3 = 4 جذر 3 سم. بطريقة الكتلة السالبة: البعد = 4 جذر 3 / 5 سم.",
