        "٣. مركز ثقل المثلث متساوي الأضلاع يبعد مسافة ثلثي الارتفاع عن الرأس $O$: $\\frac{2}{3} \\times 6\\sqrt{3} = 4\\sqrt{3}$ سم.",
        "٤. كتلة المسدس الكامل 6 ك عند $O(0, 0)$، وكتلة المثلث المقتطع ك عند $4\\sqrt{3}$ سم.",
