      "questionAr": "وعاء رقيق منتظم على شكل نصف كرة نصف قطره $r$ ووزنه $W$ يرتكز على مستوى أفقي. وُضع جسيم وزنه $w = W$ عند أوطأ نقطة في الوعاء (القاع). ما بعد مركز ثقل المجموعة الجديد عن مركز الحافة الدائرية العلوية؟",
