        "3. Particle at bottom of the bowl: weight $w = W$, located at distance $z_2 = r$ below the rim.",
        "4. Total weight: $W_{\\text{total}} = W + W = 2W$.",
        "5. $z_G = \\frac{W(\\frac{1}{2} r) + W(r)}{2W} = \\frac{\\frac{3}{2} W r}{2W} = \\frac{3}{4} r$.",
        "6. The center of gravity is at distance $\\frac{3}{4} r$ below the center of the circular rim."
