        "٢. بتشابه المثلثات، عرض الشريحة عند العمق $y$ هو $b(y) = \\frac{B}{h} y$.",
        "٣. كتلة الشريحة: $dm = k y \\times \\frac{B}{h} y dy = \\frac{k B}{h} y^2 dy$.",
        "٤. الكتلة الكلية: $M \\propto \\frac{h^3}{3}$.",
        "٥. عزم الكتلة حول الرأس: $\\propto \\frac{h^4}{4}$.",
        "٦. بعد مركز الثقل عن الرأس: $y_G = \\frac{3}{4} h$."
