      "teacherTipAr": "مقارنة: في الصفيحة المنتظمة يقع المركز عند ثلثي الارتفاع (2/3 ع)، بينما دفع زيادة الكثافة نحو القاعدة مركز الثقل لأسفل إلى (3/4 ع)."
