      "difficulty": "hots",
      "questionEn": "A uniform solid cylinder of base radius $R$ and height $H$ rests on its flat base on a horizontal surface. It is gradually tilted about a point on the circumference of its base. What is the tangent of the critical tilt angle $\\theta_c$ beyond which the cylinder will topple over?",
      "questionAr": "أسطوانة مصمتة منتظمة نصف قطر قاعدتها $R$ وارتفاعها $H$ ترتكز بقاعدتها المستوية على سطح أفقي. أُميلت تدريجياً حول نقطة على محيط قاعدتها. ما ظل زاوية الإمالة الحرجة $\\theta_c$ التي تنقلب بعدها الأسطوانة حتماً؟",
