        "3. When the cylinder is tilted about a point $P$ on the base perimeter by angle $\\theta$, the condition for toppling is that the vertical line of action of the weight falls outside the contact point $P$.",
        "4. At the verge of toppling, the line $PG$ is vertical.",
        "5. The geometry of the cylinder gives $\\tan \\theta_c = \\frac{R}{H/2} = \\frac{2R}{H}$."
