        "٣. عند إمالة الأسطوانة حول نقطة $P$ على حافة القاعدة، يكون شرط الانقلاب هو خروج خط عمل الوزن خارج نقطة الارتكاز.",
        "٤. على وشك الانقلاب، يكون المستقيم $PG$ رأسياً تماماً.",
