      "questionAr": "قالب مكعب مصمت منتظم طول ضلعه $a$ يرتكز على مستوى خشن تزداد زاوية ميله $\\alpha$ على الأفقي تدريجياً. بافتراض أن الاحتكاك كافٍ تماماً لمنع الانزلاق، عند أي زاوية ميل $\\alpha$ سينقلب المكعب؟",
