      "difficulty": "hots",
      "questionEn": "A uniform wire is bent into a complete rectangular frame $ABCD$ with sides $AB = 12\\text{ cm}$ and $BC = 16\\text{ cm}$. When the frame is suspended freely from vertex $A$, what is the angle that diagonal $AC$ makes with the vertical plumb line in equilibrium?",
      "questionAr": "سلك منتظم ثُني على شكل إطار مستطيل مغلق $ABCD$ طولا بعديه $AB = 12\\text{ cm}$ و $BC = 16\\text{ cm}$. عند تعليق الإطار تعليقاً حراً من الرأس $A$، ما قياس الزاوية التي يصنعها القطر $AC$ مع الخط الرأسي في موضع الاتزان؟",
