        "2. By reflective symmetry across both midline axes, the center of gravity $G$ of the wire frame is at the geometric center of the rectangle.",
        "3. The geometric center of any rectangle is the midpoint of its diagonals, meaning $G$ lies on the diagonal $AC$.",
        "4. When the body is suspended freely from vertex $A$, the equilibrium vertical plumb line passes through $A$ and $G$.",
        "5. Since both $A$ and $G$ lie on the diagonal $AC$, the diagonal $AC$ itself is the vertical plumb line!",
